// Independently reconstruct each held-out arm from its shard. No producer import.
use std::collections::HashMap;use std::fs;
const P:i64=1009;const N:i64=1013;const TARGETS:[i64;8]=[37,83,191,349,613,769,887,997];
#[derive(Clone,Copy,Eq,PartialEq,Hash,Debug)]enum Pt{O,A(i64,i64)}
fn m(x:i64,n:i64)->i64{x.rem_euclid(n)}
fn inv(x:i64,n:i64)->i64{let(mut a,mut b,mut u,mut v)=(m(x,n),n,1,0);while b!=0{let q=a/b;(a,b)=(b,a-q*b);(u,v)=(v,u-q*v)}assert_eq!(a,1);m(u,n)}
fn neg(p:Pt)->Pt{match p{Pt::O=>p,Pt::A(x,y)=>Pt::A(x,m(-y,P))}}
fn plus(a:Pt,b:Pt)->Pt{match(a,b){(Pt::O,v)|(v,Pt::O)=>v,(Pt::A(x,y),Pt::A(u,v))=>{if x==u&&m(y+v,P)==0{return Pt::O}let s=if x==u{m((3*x*x+1)*inv(2*y,P),P)}else{m((v-y)*inv(u-x,P),P)};let xx=m(s*s-x-u,P);Pt::A(xx,m(s*(x-xx)-y,P))}}}
fn mul(mut k:i64,mut p:Pt)->Pt{if k<0{k=-k;p=neg(p)}let mut out=Pt::O;while k>0{if k&1!=0{out=plus(out,p)}p=plus(p,p);k>>=1}out}
fn base(n:usize)->Vec<Pt>{let mut out=Vec::new();for x in 0..P{for y in 0..P{if m(y*y-x*x*x-x-14,P)==0{out.push(Pt::A(x,y));break}}if out.len()==n{break}}out}
fn table(b:&[Pt])->HashMap<Pt,(usize,usize)>{let mut t=HashMap::new();for i in 0..b.len(){for j in i..b.len(){t.entry(plus(b[i],b[j])).or_insert((i,j));}}t}
fn step(s:&mut u64)->u64{*s^=*s<<13;*s^=*s>>7;*s^=*s<<17;*s}
fn rank(rows:&[Vec<i64>],width:usize)->(usize,Vec<Vec<i64>>){let mut a=rows.to_vec();let mut h=0;for j in 0..width{if let Some(k)=(h..a.len()).find(|&k|m(a[k][j],N)!=0){a.swap(h,k);let p=inv(a[h][j],N);for v in &mut a[h]{*v=m(*v*p,N)}let pivot=a[h].clone();for i in 0..a.len(){if i!=h{let z=a[i][j];for c in j..a[i].len(){a[i][c]=m(a[i][c]-z*pivot[c],N)}}}h+=1}}(h,a)}
fn item<'a>(t:&'a[&str],k:&str)->&'a str{t.iter().find_map(|s|s.strip_prefix(k)).expect(k)}
fn main(){let g=Pt::A(0,425);let count=1+(0..P).flat_map(|x|(0..P).map(move|y|Pt::A(x,y))).filter(|&p|match p{Pt::O=>false,Pt::A(x,y)=>m(y*y-x*x*x-x-14,P)==0}).count();assert_eq!(count,1013);assert_eq!(mul(N,g),Pt::O);let mut checked=0;let mut censored=0;for d in TARGETS{let path=format!("WS68_YIELD_HELDOUT.target{d}.stdout");let raw=fs::read_to_string(path).unwrap();let lines:Vec<&str>=raw.lines().collect();assert_eq!(lines.len(),3);let q=mul(d,g);for (idx,line) in lines.iter().enumerate(){let t:Vec<&str>=line.split_whitespace().collect();let policy=item(&t,"policy=");assert_eq!(policy,["fixed8","fixed16","yield64"][idx]);assert_eq!(item(&t,"target=").parse::<i64>().unwrap(),d);let x:i64=item(&t,"q=A(").trim_end_matches(',').parse().unwrap();let y:i64=t.iter().find(|s|s.ends_with(')')).unwrap().trim_end_matches(')').parse().unwrap();assert_eq!(q,Pt::A(x,y));let attempts=item(&t,"attempts=").parse::<usize>().unwrap();let reported_hits=item(&t,"hits=").parse::<usize>().unwrap();let mut b=if policy=="fixed16"{16}else{8};let mut fb=base(b);let mut lookup=table(&fb);let mut state=0x6e71_2026_1124u64^((x as u64)<<32)^(y as u64);let mut digest=0xcbf2_9ce4_8422_2325u64;let mut hits=0;let mut rows=Vec::new();let mut anchor=vec![0;18];anchor[0]=1;anchor[17]=1;rows.push(anchor);let mut decision="not_reached";for trial in 0..attempts{if policy=="yield64"&&trial==64{if hits<2{decision="expand";b=16;fb=base(b);lookup=table(&fb)}else{decision="stay"}}let a=(step(&mut state)%N as u64)as i64;digest^=a as u64;digest=digest.wrapping_mul(0x100000001b3);let r=plus(mul(a,g),q);if let Some(&(i,j))=lookup.get(&r){assert_eq!(plus(fb[i],fb[j]),r);let mut row=vec![0;18];row[i]+=1;row[j]+=1;row[16]=-1;row[17]=a;rows.push(row);hits+=1}}assert_eq!(hits,reported_hits);assert_eq!(format!("{digest:016x}"),item(&t,"candidate_prefix_fnv64="));assert_eq!(decision,item(&t,"decision="));assert_eq!(b,item(&t,"final_base=").parse::<usize>().unwrap());let rb=rank(&rows.iter().map(|r|r[..16].to_vec()).collect::<Vec<_>>(),16).0;let(ra,z)=rank(&rows,17);assert_eq!(rb,item(&t,"rank_base=").parse::<usize>().unwrap());assert_eq!(ra,item(&t,"rank_aug=").parse::<usize>().unwrap());let ans=z.iter().find(|row|row[..16].iter().all(|&v|v==0)&&row[16]!=0).map(|row|m(row[17]*inv(row[16],N),N));let pinned=item(&t,"pinned=")=="true";assert_eq!(pinned,ans.is_some());if pinned{let recovered=item(&t,"recovered=").parse::<i64>().unwrap();assert_eq!(ans,Some(recovered));assert_eq!(recovered,d);assert_eq!(mul(recovered,g),q)}else{assert_eq!(attempts,512);assert_eq!(item(&t,"recovered="),"-1");censored+=1}checked+=1;println!("target={d} policy={policy} point=true stream=true hits={hits} rank_base={rb} rank_aug={ra} pinned={pinned}")}}println!("arms_checked={checked} censored={censored} curve_count={count}");}
